INSERT INTO wms.shipment(order_id, carrier, tracking_no, shipped_at)
             SELECT o.order_id, e.carrier, e.tracking_no, e.shipped_at FROM t_exp e JOIN wms.orders o ON o.order_no = e.order_no;
DROP TABLE IF EXISTS wms._order_no_raw;
COMMIT;
SELECT 'orders' t, count(*) FROM wms.orders UNION ALL SELECT 'order_line', count(*) FROM wms.order_line UNION ALL SELECT 'shipment', count(*) FROM wms.shipment UNION ALL SELECT 'inventory', count(*) FROM wms.inventory;
